package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookDiscardIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void discarding_a_book_returns_200_with_discarded_status() throws Exception {
        String bookId = registerBook("폐기할 책");

        mockMvc.perform(post("/books/{bookId}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(bookId))
                .andExpect(jsonPath("$.title").value("폐기할 책"))
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarded_book_cannot_be_loaned() throws Exception {
        String bookId = registerBook("빌릴 수 없는 책");
        String memberId = registerMember("김민지");
        mockMvc.perform(post("/books/{bookId}/discard", bookId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void book_on_loan_cannot_be_discarded_until_returned() throws Exception {
        String bookId = registerBook("대출 중 폐기 시도 책");
        String memberId = registerMember("김민지");
        String loanId = loan(bookId, memberId);

        mockMvc.perform(post("/books/{bookId}/discard", bookId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_ON_LOAN"));

        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/books/{bookId}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_an_unknown_book_returns_404() throws Exception {
        mockMvc.perform(post("/books/{bookId}/discard", UUID.randomUUID().toString()))
                .andExpect(status().isNotFound());
    }

    private String registerMember(String name) throws Exception {
        String body = mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String body = mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("id").asText();
    }

    private String loan(String bookId, String memberId) throws Exception {
        String body = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("loanId").asText();
    }

    private String loanRequest(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
    }

    record LoanBody(String bookId, String memberId) {
    }
}

